package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaZhDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("三个 Quls（Mu'awwidhat）", "（Surah al-Ikhlas）说：他是安拉，独一者。安拉，自足者。他既不生育也不出生。没有人可以与他相比。\n\n（《法拉克古兰经》）说：我寻求黎明之主的庇护，免受他所创造的邪恶，免受黑暗降临时的邪恶，免受那些吹结者的邪恶，以及来自嫉妒者嫉妒时的邪恶。\n\n（《古兰经》）说：我向人类之主、人类之王、人类之神寻求庇护，免受隐退的低语者的邪恶侵害，他从精灵和人类中向人类的心中低语。", "这三章每天早晚各三次，睡觉前吹入手中，然后擦在身上。", "早晚念三遍，足以抵一切事。"),
        "dua_sabr" to DuaText("为了耐心和坚定", "我们的主，请将耐心浇灌在我们身上，使我们的脚步坚定，并帮助我们对抗不信的人。", "在困难和对抗的时候。", "塔鲁特军队的二人。"),
        "dua_rabbana_innana_amanna" to DuaText("宽恕和防火保护", "我们相信我们的主，请宽恕我们的罪孽并保护我们免受火的惩罚。", "古兰经二重唱。", "敬畏上帝的品质中提到了杜阿。"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("我们的事务指南 (Ashab al-Kahf)", "我们的主，请赐予我们怜悯，并在我们的事务中为我们准备正确的指导。", "洞穴人的杜阿。", "决策和困难情况的指导。"),
        "dua_musa_faqir" to DuaText("穆萨杜阿 (AS) 供养", "我的主啊，我确实需要您赐给我的任何好处。", "寻求供给和善——Madyan 的穆萨 (AS) 的二人组。", "在这次杜阿之后，真主赐予穆萨(AS)一个家庭、工作和妻子。"),
        "dua_ayyub" to DuaText("疾病中的阿尤布杜阿 (AS)", "（我的主，）伤害触动了我，而您是仁慈者中最仁慈的。", "在疾病和痛苦中。", "安拉消除了阿尤布 (AS) 的痛苦。"),
        "dua_husn_khatimah" to DuaText("作为穆斯林而死（优素福 AS）", "天地的创造者，您是我今世和后世的保护者。让我以穆斯林的身份死去，并与正义者一起加入我的行列。", "两人的对决，才有一个美好的结局。", "先知优素福的二重奏 (AS)。"),
        "dua_shaitan_hamazat" to DuaText("远离恶魔低语的避难所", "我的主啊，我向你寻求庇护，免受魔鬼的低语，我的主，我向你寻求庇护，以免他们靠近我。", "躲避撒旦的低语。", "古兰经中寻求庇护的二重奏。"),
        "dua_bad_character" to DuaText("远离不良品格", "安拉啊，我向你寻求庇护，远离不良品格、恶行和邪恶欲望。", "远离不良品格、行为和欲望。", "躲避先知 ﷺ 的双重庇护。"),
        "dua_zawal_nimah" to DuaText("避免失去祝福", "安拉啊，我向你寻求庇护，以免失去你的祝福，避免你所赐予的福祉的改变，避免你突然的惩罚和你所有的不悦。", "避免失去福报和突如其来的灾难。", "先知 ﷺ 的二重唱。"),
        "dua_useless_knowledge" to DuaText("远离无益的知识", "安拉啊，我向你寻求庇护，远离无益的知识，远离恐惧的心，远离永不满足的灵魂，远离未得到回应的杜阿。", "远离无用的知识和一颗不敬畏安拉的心。", "躲避先知 ﷺ 的双重庇护。"),
        "dua_beneficial_knowledge" to DuaText("有益的知识和清真 Rizq", "安拉啊，我祈求您赐予有益的知识、纯洁的供给和公认的行为。", "晨祷后。", "先知 ﷺ 在晨礼礼拜后如此说道。"),
        "dua_leprosy_diseases" to DuaText("远离严重疾病", "安拉啊，我向你寻求庇护，远离白癜风、疯狂、麻风病和所有邪恶的疾病。", "预防严重疾病。", "维护健康的圣行杜阿。"),
        "dua_fear_people" to DuaText("对敌人或压迫者的恐惧", "安拉啊，我们将您置于他们面前，并寻求您的庇护，免受他们的邪恶。", "当担心一个人或一个人受到伤害时。", "先知 ﷺ 在害怕人民时说了这句话。"),
        "dua_shirk_protection" to DuaText("防止隐藏的推卸责任", "安拉啊，我向您寻求庇护，避免故意将任何事情与您联系起来，并为我无意识所做的事情寻求您的宽恕。", "为了避免炫耀和隐藏的推卸。", "隐藏的逃避比蚂蚁的爬行还要隐蔽。"),
        "dua_rain" to DuaText("下雨时", "安拉啊，（赐予）有益的雨水。", "下雨的时候。", "雨是接受杜阿的时候。"),
        "dua_after_rain" to DuaText("雨后", "真主的恩惠和仁慈赐予了我们雨水。", "雨后。", "说这句话的人是安拉的信徒。"),
        "dua_istisqa" to DuaText("求雨 (Istisqa)", "安拉啊，请赐予我们雨水（三次）。", "没有下雨的时候。", "先知 ﷺ 在周五的布道中做了这个杜阿，当时下雨了。"),
        "dua_heavy_rain" to DuaText("雨太大", "安拉啊，（让它落在）我们周围，而不是落在我们身上。", "当雨太大的时候。", "云层在先知 ﷺ 的杜阿中消散。"),
        "dua_wind" to DuaText("当风吹过的时候", "安拉啊，我祈求你赐予它的善，它内在的善以及它所带来的善，我向你寻求庇护，使其免受它的邪恶，它里面的邪恶以及它所带来的邪恶。", "当强风或暴风雨吹来时。", "先知 ﷺ 在暴风雨期间做出了这个杜阿。"),
        "dua_thunder" to DuaText("闻雷声", "荣耀归于那一位，雷霆因他的赞美而荣耀他，天使因敬畏他而荣耀他。", "听到雷声——阿卜杜拉·伊本·阿兹-祖拜尔 (Abdullah ibn az-Zubayr) 的做法 (RA)。", "摘自古兰经 (13:13)。"),
        "dua_new_moon" to DuaText("看见新月", "安拉啊，让这轮月亮带着祝福、信仰、安全和伊斯兰教升起在我们上方。 （哦月亮，）我的主和你的主是真主。", "看到新月时。", "每个新月的圣行杜阿。"),
        "dua_janaza_adult" to DuaText("贾纳扎祈祷（成人）", "安拉啊，宽恕我们的生者和死者、在场的和不在场的、我们的年轻人和老年人、我们的男人和女人。安拉啊，无论你让我们谁活下去，你都让他因伊斯兰教而活；无论你让我们谁死，你都让他因信仰而死。", "在葬礼祈祷的第三次大诵之后。", "已故成年人的圣行杜阿。"),
        "dua_janaza_child" to DuaText("贾纳扎祈祷（儿童）", "安拉啊，请让他成为我们的先行者（和主人），让他成为我们的奖赏和财富，让他成为我们的代祷者，他的代祷被接受。", "在孩子的葬礼祈祷中（对女孩说“ij'alhā”）。", "哈纳菲派所奉行的圣行。"),
        "dua_mayyit_awf" to DuaText("死者的详细杜阿", "安拉啊，宽恕他，怜悯他，赐予他福祉并宽恕他。尊敬地接待他，宽敞他的坟墓，用水、雪和冰雹清洗他，像清洗白衣上的污垢一样清洗他的罪孽。", "在葬礼或为死者祈祷时。", "Awf ibn Malik (RA) 希望他就是那个死者。"),
        "dua_visiting_graves" to DuaText("参观坟墓", "这些家庭的信仰者和穆斯林居民啊，愿你们平安。如果真主愿意，我们也将加入你们。我祈求真主保佑我们和你们幸福。", "进入墓地时。", "参观坟墓会让人想起死亡和后世。"),
        "dua_closing_eyes" to DuaText("死者闭上眼睛后", "安拉啊，宽恕（名字），提高他在受引导者中的地位，成为他留下的人中的继承者。诸世界之主啊，宽恕我们和他；使他的坟墓宽敞并充满光明。", "当死者闭上眼睛时（提及他的名字）。", "先知 ﷺ 为阿布萨拉马 (RA) 做了这个杜阿。"),
        "dua_condolence" to DuaText("哀悼（塔兹亚）", "当然，真主所索取的都属于他，他所给予的也都属于他，他的一切都有一个指定的期限，所以要有耐心并希望得到回报。", "向死者家属表示哀悼。", "先知 ﷺ 将此消息发送给他的女儿。"),
        "dua_placing_in_grave" to DuaText("将死者安葬在坟墓中", "以真主之名并遵循真主使者 ﷺ 的道路。", "将死者放入坟墓时。", "埋葬的圣行杜阿。"),
        "dua_sneezing" to DuaText("打喷嚏", "一切赞美都归于安拉。 ——愿真主怜悯你。 — 愿真主引导你并纠正你的事务。", "打喷嚏时；听者说“Yarhamukallah”，然后打喷嚏的人回答。", "这是一个穆斯林相对于另一个穆斯林的权利之一。"),
        "dua_toilet_enter" to DuaText("进入厕所", "以安拉的名义。安拉啊，我向你寻求庇护，免受男性和女性不纯洁的精灵的伤害。", "左脚踏入厕所前。", "比斯米拉成为精灵和人类之间的一道屏障。"),
        "dua_toilet_exit" to DuaText("离开厕所", "（真主啊）我寻求您的宽恕。", "右脚走出厕所时。", "先知 ﷺ 在离开厕所时说了这句话。"),
        "dua_thanking" to DuaText("感谢某人", "愿真主以美好回报你。", "当有人帮你一个忙时。", "谁说这句话，就已经充分表达了他的谢意。"),
        "dua_love_for_allah" to DuaText("当有人说“我因安拉而爱你”时", "愿他（安拉）为了你爱我而爱你。", "当有人说“我为了安拉而爱你”时。", "圣行回应了为安拉而爱的事。"),
        "dua_seeing_muslim_smile" to DuaText("问候（萨拉姆）", "愿安拉赐予你们平安，愿真主赐福给你们。", "当遇到穆斯林时。", "念完完整的萨拉姆可以获得三十善行。"),
        "dua_dressing" to DuaText("穿衣服", "所有的赞美都归于安拉，他给了我这件衣服，并且在我没有任何力量的情况下为我提供了它。", "穿衣服的时候。", "过去的罪孽得到宽恕的好消息。"),
        "dua_rooster_donkey" to DuaText("听到公鸡或驴的叫声", "安拉啊，我向您祈求您的恩惠（公鸡）。 — 我向安拉寻求庇护，免受恶魔（Shaytan）的伤害（驴子）。", "当听到公鸡祈求安拉的恩赐时；听到驴子的叫声寻求恶魔的庇护。", "公鸡看到天使，驴看到魔鬼。"),
        "dua_something_liked" to DuaText("看到令人钦佩的东西（对抗邪恶之眼）", "安拉所愿的。安拉啊，保佑它。", "当看到某人拥有令人钦佩的东西时，请祈祷祝福。", "祈求祝福可以防止邪眼。"),
        "dua_sell_buy_debt_repaid" to DuaText("偿还债务时", "愿真主保佑您的家庭和财富。", "供贷款人偿还债务时使用。", "贷款的回报是感谢和偿还。"),
        "dua_talbiyah" to DuaText("塔尔比耶", "我在这里，阿拉啊，我在这里。我在这里，你没有伴侣，我在这里。当然，所有的赞美、祝福和统治权都属于您。你没有伴侣。", "进入受戒后大声喊叫。", "朝觐和副朝的标志。"),
    )
}
